/** Client-local names; never used for identity, credentials, or routing. */
export function environmentName(value: string): string {
  const name = value.trim();
  if (!name || name.length > 512 || /[\u0000-\u001f\u007f]/.test(name)) {
    throw new TypeError("Enter an environment name of 1 to 512 characters without control characters.");
  }
  return name;
}

/** Only the historical autogenerated form is normalized; custom labels survive. */
export function defaultEnvironmentName(label: string, host?: string): string {
  const trimmed = label.trim();
  const legacy = /^GitGui on\s+(This computer|\S+)$/i.exec(trimmed);
  const plain = legacy?.[1] ?? trimmed;
  return !plain || /^this computer$/i.test(plain) ? host?.trim() || "This computer" : plain;
}

export function parseEnvironmentNames(value: unknown): Readonly<Record<string, string>> {
  if (typeof value !== "object" || value === null || Array.isArray(value)) return {};
  return Object.fromEntries(Object.entries(value).flatMap(([id, name]) => {
    try { return typeof name === "string" ? [[id, environmentName(name)]] : []; }
    catch { return []; }
  }));
}
